/**
 * USGS Earthquake Hazards Program real-time feeds.
 * https://earthquake.usgs.gov/earthquakes/feed/v1.0/geojson.php
 *
 * No API key required. Feeds are regenerated by USGS every minute.
 */

export type WindowId = "hour" | "day" | "week" | "month";

export interface FeedWindow {
  id: WindowId;
  /** Short label used in the segmented control. */
  label: string;
  /** Long label used in prose ("in the past 24 hours"). */
  longLabel: string;
  /** Duration of the window in milliseconds. */
  durationMs: number;
  /** USGS feed slug. */
  slug: string;
  /** Completeness caveat shown next to the control, if the feed is filtered. */
  note: string | null;
}

export const FEED_WINDOWS: FeedWindow[] = [
  {
    id: "hour",
    label: "1H",
    longLabel: "past hour",
    durationMs: 3_600_000,
    slug: "all_hour",
    note: null,
  },
  {
    id: "day",
    label: "24H",
    longLabel: "past 24 hours",
    durationMs: 86_400_000,
    slug: "all_day",
    note: null,
  },
  {
    id: "week",
    label: "7D",
    longLabel: "past 7 days",
    durationMs: 604_800_000,
    slug: "all_week",
    note: null,
  },
  {
    id: "month",
    label: "30D",
    longLabel: "past 30 days",
    durationMs: 2_592_000_000,
    // The unfiltered 30-day feed is a 7 MB download dominated by micro-events in
    // densely instrumented regions; the M2.5+ feed is the globally comparable one.
    slug: "2.5_month",
    note: "M2.5+",
  },
];

export function feedWindow(id: WindowId): FeedWindow {
  return FEED_WINDOWS.find((w) => w.id === id) ?? FEED_WINDOWS[1];
}

export function feedUrl(id: WindowId): string {
  return `https://earthquake.usgs.gov/earthquakes/feed/v1.0/summary/${feedWindow(id).slug}.geojson`;
}

/** Alert levels come from the USGS PAGER impact model. */
export type AlertLevel = "green" | "yellow" | "orange" | "red";

export interface Quake {
  id: string;
  /** Moment / local magnitude. Null for a handful of unreviewed events. */
  mag: number;
  magType: string | null;
  /** "68 km SSW of Whitehorse, Canada" */
  place: string;
  /** "M 5.0 - 68 km SSW of Whitehorse, Canada" */
  title: string;
  /** Origin time, ms since epoch (UTC). */
  time: number;
  updated: number;
  lon: number;
  lat: number;
  /** Depth below sea level in km. Negative values exist for a few shallow events. */
  depth: number;
  /** USGS significance score, 0–1000. */
  sig: number;
  /** Number of "Did you feel it?" responses. */
  felt: number | null;
  /** Community-reported intensity (DYFI), Modified Mercalli. */
  cdi: number | null;
  /** Instrumental intensity (ShakeMap), Modified Mercalli. */
  mmi: number | null;
  alert: AlertLevel | null;
  tsunami: boolean;
  status: string;
  /** Event type: "earthquake", "quarry blast", "explosion", "ice quake"… */
  type: string;
  /** Number of seismic stations used to locate the event. */
  nst: number | null;
  /** Largest azimuthal gap between stations, degrees. Lower is better. */
  gap: number | null;
  /** Horizontal distance to the nearest station, degrees. */
  dmin: number | null;
  rms: number | null;
  net: string;
  url: string;
}

export interface FeedResult {
  quakes: Quake[];
  /** Time the feed itself was generated by USGS. */
  generated: number;
  title: string;
}

interface RawFeature {
  id?: string;
  properties?: Record<string, unknown>;
  geometry?: { coordinates?: unknown } | null;
}

function num(value: unknown): number | null {
  return typeof value === "number" && Number.isFinite(value) ? value : null;
}

function str(value: unknown): string | null {
  return typeof value === "string" && value.length > 0 ? value : null;
}

const ALERTS: AlertLevel[] = ["green", "yellow", "orange", "red"];

/**
 * Convert one raw GeoJSON feature into a `Quake`.
 * Returns null when the feature has no usable position or magnitude — a few
 * events per month arrive with a null magnitude while still being reviewed.
 */
export function parseFeature(feature: RawFeature): Quake | null {
  const coords = feature.geometry?.coordinates;
  if (!Array.isArray(coords) || coords.length < 2) return null;

  const lon = num(coords[0]);
  const lat = num(coords[1]);
  const id = str(feature.id);
  const props = feature.properties ?? {};
  const mag = num(props.mag);

  if (lon === null || lat === null || id === null || mag === null) return null;
  if (lat < -90 || lat > 90) return null;

  const time = num(props.time);
  if (time === null) return null;

  const alertRaw = str(props.alert)?.toLowerCase();

  return {
    id,
    mag,
    magType: str(props.magType),
    place: str(props.place) ?? "Unknown location",
    title: str(props.title) ?? `M ${mag.toFixed(1)}`,
    time,
    updated: num(props.updated) ?? time,
    lon,
    lat,
    depth: num(coords[2]) ?? 0,
    sig: num(props.sig) ?? 0,
    felt: num(props.felt),
    cdi: num(props.cdi),
    mmi: num(props.mmi),
    alert: ALERTS.includes(alertRaw as AlertLevel) ? (alertRaw as AlertLevel) : null,
    tsunami: num(props.tsunami) === 1,
    status: str(props.status) ?? "automatic",
    type: str(props.type) ?? "earthquake",
    nst: num(props.nst),
    gap: num(props.gap),
    dmin: num(props.dmin),
    rms: num(props.rms),
    net: str(props.net) ?? "",
    url: str(props.url) ?? `https://earthquake.usgs.gov/earthquakes/eventpage/${id}`,
  };
}

export function parseFeed(payload: unknown): FeedResult {
  const root = payload as {
    features?: unknown;
    metadata?: { generated?: unknown; title?: unknown };
  };

  if (!Array.isArray(root?.features)) {
    throw new Error("Unexpected feed payload: missing feature collection");
  }

  const quakes: Quake[] = [];
  for (const feature of root.features) {
    const quake = parseFeature(feature as RawFeature);
    if (quake) quakes.push(quake);
  }
  // USGS returns newest-first already, but the ordering is not contractual.
  quakes.sort((a, b) => b.time - a.time);

  return {
    quakes,
    generated: num(root.metadata?.generated) ?? Date.now(),
    title: str(root.metadata?.title) ?? "USGS Earthquakes",
  };
}

export async function fetchFeed(id: WindowId, signal?: AbortSignal): Promise<FeedResult> {
  const response = await fetch(feedUrl(id), { signal, cache: "no-store" });
  if (!response.ok) {
    throw new Error(`USGS feed responded with ${response.status} ${response.statusText}`);
  }
  return parseFeed(await response.json());
}
